// This code snippet demonstrates how to correctly encrypt data using AES in CBC mode with a randomized IV.
import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"errors"
	"fmt"
	"io"
)

func encryptData(key, data []byte) ([]byte, []byte, []byte, error) {
	// Choose AES-256 (key length 32 bytes)
	aesKeyLen := 32
	if len(key) < aesKeyLen {
		return nil, nil, nil, errors.New("key is too short for AES-256")
	}
	aesKey := key[:aesKeyLen]

	// Generate a random IV
	iv := make([]byte, aes.BlockSize)
	if _, err := io.ReadFull(rand.Reader, iv); err != nil {
		return nil, nil, nil, err
	}

	// Create AES cipher
	block, err := aes.NewCipher(aesKey)
	if err != nil {
		return nil, nil, nil, err
	}

	// Create a new CBC mode encryptor
	cbc := cipher.NewCBCEncryptor(block, iv)

	// Encrypt the data
	encryptedData := make([]byte, len(data))
	cbc.CryptBlocks(encryptedData, data)

	return encryptedData, iv, aesKey, nil
}

// Example usage
func main() {
	key := []byte("ThisIsA256BitKey1234567890123456")
	data := []byte("SecretDataToEncrypt")
	encryptedData, iv, aesKey, err := encryptData(key, data)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	fmt.Printf("Encrypted: %x\n", encryptedData)
	fmt.Printf("IV: %x\n", iv)
	fmt.Printf("Key: %x\n", aesKey)
}
